import{c as a,Q as t,j as i,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Flamingo: a Visual Language Model for Few-Shot Learning","description":"","frontmatter":{"url":"https://arxiv.org/abs/2204.14198","title":"Flamingo: a Visual Language Model for Few-Shot Learning","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2204.14198,"authors":["Jean-Baptiste Alayrac","Jeff Donahue","Pauline Luc","Antoine Miech","Iain Barr","Yana Hasson","Karel Lenc","Arthur Mensch","Katie Millican","Malcolm Reynolds","Roman Ring","Eliza Rutherford","Serkan Cabi","Tengda Han","Zhitao Gong","Sina Samangooei","Marianne Monteiro","Jacob Menick","Sebastian Borgeaud","Andrew Brock","Aida Nematzadeh","Sahand Sharifzadeh","Mikolaj Binkowski","Ricardo Barreira","Oriol Vinyals","Andrew Zisserman","Karen Simonyan"],"pdf_path":"pdfs/2204.14198.pdf","published_date":"2022-01-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2022-04-29-flamingo-visual-language-model-few-shot-2204-14198.md","filePath":"research/papers/2022-04-29-flamingo-visual-language-model-few-shot-2204-14198.md","lastUpdated":1785909234000}'),r={name:"research/papers/2022-04-29-flamingo-visual-language-model-few-shot-2204-14198.md"};function o(s,e,l,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="flamingo-a-visual-language-model-for-few-shot-learning" tabindex="-1">Flamingo: a Visual Language Model for Few-Shot Learning <a class="header-anchor" href="#flamingo-a-visual-language-model-for-few-shot-learning" aria-label="Permalink to &quot;Flamingo: a Visual Language Model for Few-Shot Learning&quot;">​</a></h1><p><strong>Authors:</strong> Jean-Baptiste Alayrac, Jeff Donahue, Pauline Luc, Antoine Miech, Iain Barr, Yana Hasson, Karel Lenc, Arthur Mensch, Katie Millican, Malcolm Reynolds, Roman Ring, Eliza Rutherford, Serkan Cabi, Tengda Han, Zhitao Gong, Sina Samangooei, Marianne Monteiro, Jacob Menick, Sebastian Borgeaud, Andrew Brock, Aida Nematzadeh, Sahand Sharifzadeh, Mikolaj Binkowski, Ricardo Barreira, Oriol Vinyals, Andrew Zisserman, Karen Simonyan <strong>Year:</strong> 2022 <strong>Venue:</strong> NeurIPS 2022 <strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2204.14198" target="_blank" rel="noreferrer">https://arxiv.org/abs/2204.14198</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>Building models that can be rapidly adapted to novel tasks using only a handful of annotated examples is an open challenge for multimodal machine learning research. We introduce Flamingo, a family of Visual Language Models (VLM) with this ability. We propose key architectural innovations to: (i) bridge powerful pretrained vision-only and language-only models, (ii) handle sequences of arbitrarily interleaved visual and textual data, and (iii) seamlessly ingest images or videos as inputs. Thanks to their flexibility, Flamingo models can be trained on large-scale multimodal web corpora containing arbitrarily interleaved text and images, which is key to endow them with in-context few-shot learning capabilities. We demonstrate that Flamingo models achieve new state-of-the-art few-shot results across a wide range of open-ended visual and language tasks including visual question-answering, captioning, and others.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>Novel Perceiver Resampler architecture</strong> converting variable-size visual features from a frozen vision encoder into a fixed number of visual tokens for efficient LLM ingestion regardless of input resolution or video frame count</li><li><strong>Gated cross-attention dense layers</strong> inserted between frozen LLM transformer blocks enable vision-language integration while preserving pre-trained language capabilities — the gating mechanism allows the model to learn when to attend to visual context</li><li><strong>First large-scale multimodal model capable of in-context few-shot learning</strong> on interleaved image-text sequences, analogous to GPT-3&#39;s text-only few-shot ability</li><li><strong>Pre-training on billions of web-scraped image-text pairs</strong> (ALIGN, LTIP, VTP datasets) at scale establishes the importance of diverse, naturally-occurring multimodal web data</li><li><strong>NeurIPS 2022</strong> — seminal architecture that directly influenced BLIP-2, OpenFlamingo, Otter, and the broader frozen-LLM connector paradigm</li><li>Demonstrated strong performance across both open-ended generation tasks (captioning, VQA) and classification-style tasks using a unified architecture</li><li>Showed that frozen large language models can acquire visual grounding without degrading language capabilities when connected via carefully designed cross-attention modules</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>Flamingo&#39;s architecture consists of three main components: a frozen pre-trained vision encoder (NFNet), a Perceiver Resampler, and a frozen large language model (Chinchilla) augmented with interleaved gated cross-attention layers. The vision encoder processes images or video frames into dense feature grids. The Perceiver Resampler then compresses these variable-length visual features into a fixed set of 64 visual tokens via learned queries attending to the visual features — this is the key efficiency innovation allowing the LLM to process any image regardless of resolution.</p><p>The gated cross-attention layers are inserted at fixed intervals within the frozen LLM&#39;s transformer stack. Each such layer allows the text stream to attend over the visual tokens from the most recently preceding image in the interleaved sequence. A learned tanh-gated residual connection initializes with zero weight, ensuring the frozen LLM&#39;s behavior is preserved at initialization and visual influence is introduced gradually during training.</p><p>Pre-training uses a mixture of datasets at different scales: ALIGN (1.8B image-text pairs scraped from the web with alt-text), LTIP (Long Text &amp; Image Pairs, 312M higher-quality pairs), and VTP (Video &amp; Text Pairs, 27M short video clips). The interleaved image-text format is sourced from MultiModal MassiveWeb (M3W), a 43M document web corpus preserving natural interleaving of images within text. Only the cross-attention layers and Perceiver Resampler are trained; both the vision encoder and LLM remain frozen.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Flamingo Setting</th><th>Performance</th></tr></thead><tbody><tr><td>VQAv2</td><td>4-shot</td><td>56.3% (SOTA few-shot at time)</td></tr><tr><td>COCO Captioning</td><td>4-shot</td><td>84.3 CIDEr</td></tr><tr><td>NExT-QA</td><td>4-shot</td><td>51.7%</td></tr><tr><td>VATEX (video captioning)</td><td>4-shot</td><td>36.4 CIDEr</td></tr></tbody></table><p>Flamingo (80B parameters) outperformed prior SOTA on 6 of 16 benchmarks with just 4 in-context examples, sometimes surpassing fine-tuned models that used thousands of labeled examples.</p><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>All parameters except cross-attention layers are frozen, limiting the model&#39;s ability to deeply integrate visual knowledge into its representations</li><li>The Perceiver Resampler compresses visual information into 64 tokens, which may lose fine-grained spatial detail needed for tasks like counting or precise localization</li><li>Few-shot performance is bounded by the LLM&#39;s language priors — the model can &quot;hallucinate&quot; plausible but visually incorrect answers</li><li>Pre-training data quality is noisy (web-scraped); image-text alignment is imperfect</li><li>Compute cost of 80B parameter model limits accessibility; subsequent works (OpenFlamingo, BLIP-2) addressed this with smaller, more efficient designs</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>Flamingo proved that <strong>large frozen language models can be efficiently extended to vision through lightweight architectural additions</strong>, rather than expensive end-to-end multimodal pre-training. The key insight — insert cross-attention bridges while keeping both vision encoder and LLM frozen — dramatically reduces training cost and preserves language capabilities.</p><p>The in-context few-shot learning ability is particularly valuable for practitioners: you can adapt Flamingo to a new visual task with just a handful of examples in the prompt, with no fine-tuning required. This mirrors how practitioners use GPT-3/4 for NLP tasks and extends that paradigm to vision. The Perceiver Resampler and gated cross-attention patterns became architectural blueprints for BLIP-2&#39;s Q-Former and numerous subsequent multimodal systems.</p>',24)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
